    long long min_tickets = -1;
    int best_x = -1;
    int best_y = -1;

    for (int x = 1; x <= maxx; ++x) {
        for (int y = 1; y <= maxy; ++y) {
            int lucky_count = 0;
            for (int a = 1; a <= x; ++a) {
                for (int b = 1; b <= y; ++b) {
                    if (a * b == rev(a) * rev(b)) {
                        lucky_count++;
                    }
                }
            }

            if (lucky_count >= w) {
                long long tickets = (long long)x * y;
                if (min_tickets == -1 || tickets < min_tickets) {
                    min_tickets = tickets;
                    best_x = x;
                    best_y = y;
                }
            }
        }
    }

    if (best_x == -1) {
        cout << -1 << endl;
    } else {
        cout << best_x << " " << best_y << endl;
    }

    return 0;
}

