        for (int i = 1; i < s.length(); ++i) {
            string left_str = s.substr(0, i);
            string right_str = s.substr(i);
            long long left = stoll(left_str);
            long long right = stoll(right_str);
            max_product = max(max_product, left * right);
        }
        n = max_product;
        steps++;
        if (steps > 100) return -1;
    }
    return steps;
}

