                    if(b[i] >= diff){
                        b[i] -= diff;
                    } else {
                        valid = false;
                        break;
                    }
                }
            }

            if (valid) {



                bool increasing = true;
                for (int i = 1; i < k; ++i) {
                    if (b[i] <= b[i - 1]) {
                        increasing = false;
                        break;
                    }
                }

                bool decreasing = true;
                for (int i = k; i < n - 1; ++i) {
                    if (b[i] <= b[i + 1]) {
                        decreasing = false;
                        break;
                    }
                }

