    for (int i = 0; i < (1 << n); ++i) {
      string current_s = s;
      string ops = "";

      for (int j = 0; j < n; ++j) {
        if ((i >> j) & 1) {



          if (j > 0) {
            ops += "L";
            swap(current_s[j], current_s[j - 1]);
